package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.escort.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class EscortPlayTest {
    static QuestCatalog catalog(){var q=QuestCatalogTest.quest("survey_marker","guide");q.remove("objective");var goals=new ArrayList<Map<String,Object>>();for(int i=0;i<2;i++)goals.add(new HashMap<>(Map.of("description","현재 호위 목표","interaction","escort:courier","min-x",i==0?0:8,"max-x",i==0?12:20,"min-y",63,"max-y",67,"min-z",0,"max-z",10)));q.put("objectives",goals);return QuestCatalog.parse(List.of(QuestCatalogTest.npc("guide",3)),List.of(q));}
    static QuestRules rules(){return new QuestRules(Map.of("survey_marker",new QuestRules.Rule(QuestRules.Restart.CHECKPOINT,Set.of("OBJECTIVE"),List.of(1),0,null)),Map.of());}
    static Map<String,Object> definition(){return new HashMap<>(Map.of("id","courier","quest","survey_marker","name","개인 전달자","speed",.8,"follow-distance",12,"legs",List.of(Map.of("objective",0,"path",List.of(List.of(3,64,3),List.of(6,64,3),List.of(9,64,3))),Map.of("objective",1,"path",List.of(List.of(9,64,3),List.of(12,64,3),List.of(15,64,3))))));}
    static Map<String,Object> root(Map<String,Object> row){return Map.of("format",1,"escorts",List.of(row));}
    static final class Actor implements EscortPlay.Actor{
        final ServerProgressAccess.Context ctx;final Object token=new Object();UUID world=UUID.randomUUID();long generation=1;boolean valid=true,allowed=true;EscortContent.Point point=new EscortContent.Point(3,64,3);
        Actor(ServerProgressAccess.Context ctx){this.ctx=ctx;}public ServerProgressAccess.Context context(){return ctx;}public Object token(){return token;}public UUID world(){return world;}public long generation(){return generation;}public boolean current(){return valid;}public boolean allowed(String q){return allowed;}public EscortContent.Point position(){return point;}
    }
    static final class Body implements EscortPlay.Body{
        final UUID id=UUID.randomUUID();EscortContent.Point point,target;boolean alive=true,removed,failMove,failRemove;int moves;
        Body(EscortContent.Point p){point=p;}public UUID id(){return id;}public boolean alive(){return alive&&!removed;}public EscortContent.Point position(){return point;}public void move(EscortContent.Point p,double speed){if(failMove)throw new IllegalStateException();target=p;moves++;}public void stop(){}public void remove(){if(failRemove)throw new IllegalStateException();removed=true;}
    }
    static final class F {
        final PersonalQuestTest.Fixture f=new PersonalQuestTest.Fixture();final QuestCatalog catalog=catalog();final EscortContent content=EscortContent.parse(root(definition()),catalog,rules());final List<Body> bodies=new ArrayList<>();final Actor actor=new Actor(f.ctx(f.a,f.p));final EscortPlay play=new EscortPlay(content,catalog,f.quests,(a,d,l)->{var b=new Body(l.start());bodies.add(b);return b;},f.queue::add,()->{});
        F(){f.quests.rules(rules());}void accept(Actor a){var open=f.quests.open(a.ctx,"survey_marker",a.token,a::current);f.pump();f.quests.accept(open.toCompletableFuture().join(),catalog.quest("survey_marker"));commit();}
        void commit(){f.store.commit.getLast().run();f.pump();}EscortPlay.Attempt start(Actor a){var work=play.start(a,"survey_marker");f.pump();return work.toCompletableFuture().join();}
        void reach(EscortPlay.Attempt attempt){var b=(Body)attempt.body();for(int i=0;i<8&&(attempt.phase()==EscortPlay.Phase.ACTIVE||attempt.phase()==EscortPlay.Phase.WAITING);i++){play.tick();if(b.target!=null)b.point=b.target;}}
        QuestStore.Saved saved(Actor a){return f.store.rows.get(f.store.key(a.ctx));}
    }
    @Test void unacceptedUnknownOrWrongLocationCannotSpawnAndPendingStartCoalesces(){var x=new F();var unaccepted=x.play.start(x.actor,"survey_marker");x.f.pump();assertTrue(unaccepted.toCompletableFuture().isCompletedExceptionally());assertTrue(x.bodies.isEmpty());assertTrue(x.play.start(x.actor,"unknown").toCompletableFuture().isCompletedExceptionally());x.accept(x.actor);x.actor.point=new EscortContent.Point(50,64,3);var far=x.play.start(x.actor,"survey_marker");x.f.pump();assertTrue(far.toCompletableFuture().isCompletedExceptionally());x.actor.point=new EscortContent.Point(3,64,3);var first=x.play.start(x.actor,"survey_marker");assertSame(first,x.play.start(x.actor,"survey_marker"));x.f.pump();assertEquals(1,x.bodies.size());assertSame(first.toCompletableFuture().join(),x.start(x.actor));assertTrue(x.play.start(x.actor,"survey_marker",new QuestStore.Saved(QuestStore.Phase.ACTIVE,99,0)).toCompletableFuture().isCompletedExceptionally());}
    @Test void targetArrivalNeedsOwnerAndStoredGoalAdvancesOnlyAfterCommit(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);x.reach(a);assertEquals(EscortPlay.Phase.WAITING,a.phase());assertEquals(0,x.saved(x.actor).objectiveIndex());x.actor.point=new EscortContent.Point(9,64,3);x.reach(a);assertEquals(EscortPlay.Phase.COMPLETING,a.phase());assertEquals(0,x.saved(x.actor).objectiveIndex());x.commit();assertEquals(EscortPlay.Phase.DONE,a.phase());assertEquals(1,x.saved(x.actor).objectiveIndex());int writes=x.f.store.pending.size();x.play.died(a.body().id());x.play.tick();assertEquals(writes,x.f.store.pending.size());}
    @Test void registeredDeathFailsOnceAndCheckpointRetryKeepsPriorCompletedLeg(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);x.actor.point=new EscortContent.Point(9,64,3);x.reach(a);x.commit();var next=x.start(x.actor);x.play.died(next.body().id());x.play.died(next.body().id());assertEquals(EscortPlay.Phase.FAILING,next.phase());assertEquals(QuestStore.Phase.ACTIVE,x.saved(x.actor).phase());x.commit();assertEquals(QuestStore.Phase.FAILED,x.saved(x.actor).phase());assertEquals(1,x.saved(x.actor).objectiveIndex());var opened=x.f.quests.open(x.actor.ctx,"survey_marker",x.actor.token,x.actor::current);x.f.pump();x.f.quests.retry(opened.toCompletableFuture().join(),x.catalog.quest("survey_marker"));x.commit();assertEquals(1,x.start(x.actor).objective());}
    @Test void anotherPersonalOwnerAndProgressNeverReceiveCreditOrForeignBodyEvent(){var x=new F();x.accept(x.actor);var peer=new Actor(x.f.ctx(x.f.a,x.f.p2));peer.world=x.actor.world;x.accept(peer);var own=x.start(x.actor);var other=x.start(peer);x.play.died(UUID.randomUUID());x.actor.point=new EscortContent.Point(9,64,3);x.reach(own);x.commit();assertEquals(1,x.saved(x.actor).objectiveIndex());assertEquals(0,x.saved(peer).objectiveIndex());assertNotEquals(own.body().id(),other.body().id());assertFalse(((Body)other.body()).removed);}
    @Test void disconnectOrWorldGenerationChangeRemovesOnlyActorAndPreservesQuest(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);var before=x.saved(x.actor);x.actor.valid=false;x.play.left(x.actor.token);assertEquals(EscortPlay.Phase.CLOSED,a.phase());assertEquals(before,x.saved(x.actor));x.play.died(a.body().id());var fresh=new Actor(x.actor.ctx);var resumed=x.start(fresh);fresh.generation++;x.play.tick();assertEquals(EscortPlay.Phase.CLOSED,resumed.phase());assertEquals(before,x.saved(x.actor));}
    @Test void saveFailurePreservesOriginalAndHoldCannotAutomaticallyRestart(){var x=new F();x.accept(x.actor);var before=x.saved(x.actor);var a=x.start(x.actor);x.actor.point=new EscortContent.Point(9,64,3);x.reach(a);x.f.store.pending.getLast().completeExceptionally(new StorageFailure("quest","COMMIT_UNKNOWN"));x.f.pump();assertEquals(EscortPlay.Phase.HOLD,a.phase());assertEquals(before,x.saved(x.actor));assertTrue(x.play.barrier(x.f.a).toCompletableFuture().isCompletedExceptionally());assertTrue(x.play.start(x.actor,"survey_marker").toCompletableFuture().isCompletedExceptionally());}
    @Test void lateCommitAfterLogoutDoesNotApplySuccessOrAllowNewAutomaticAttempt(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);x.actor.point=new EscortContent.Point(9,64,3);x.reach(a);x.actor.valid=false;x.play.left(x.actor.token);x.commit();assertEquals(EscortPlay.Phase.HOLD,a.phase());assertEquals(1,x.saved(x.actor).objectiveIndex());var fresh=new Actor(x.actor.ctx);assertTrue(x.play.start(fresh,"survey_marker").toCompletableFuture().isCompletedExceptionally());}
    @Test void ownerLeavingAreaPausesWithoutFailureAndTargetEscapingFails(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);x.actor.point=new EscortContent.Point(80,64,3);x.play.tick();assertEquals(EscortPlay.Phase.WAITING,a.phase());assertEquals(QuestStore.Phase.ACTIVE,x.saved(x.actor).phase());x.actor.point=new EscortContent.Point(3,64,3);((Body)a.body()).point=new EscortContent.Point(80,64,3);x.play.tick();x.commit();assertEquals(QuestStore.Phase.FAILED,x.saved(x.actor).phase());}
    @Test void movementOrCleanupFailureIsHoldAndNeverACompletedStep(){var x=new F();x.accept(x.actor);var a=x.start(x.actor);((Body)a.body()).failMove=true;x.play.tick();assertEquals(EscortPlay.Phase.HOLD,a.phase());assertEquals(0,x.saved(x.actor).objectiveIndex());var y=new F();y.accept(y.actor);var b=y.start(y.actor);((Body)b.body()).failRemove=true;y.play.left(y.actor.token);assertEquals(EscortPlay.Phase.HOLD,b.phase());assertTrue(y.play.barrier(y.f.a).toCompletableFuture().isCompletedExceptionally());((Body)b.body()).failRemove=false;y.play.close();}
    @Test void parserRejectsUnboundLegUnsafePathAndMissingFailurePolicy(){assertThrows(IllegalArgumentException.class,()->EscortContent.parse(root(definition()),catalog(),QuestRules.empty()));for(String defect:List.of("speed","follow-distance","legs","path","duplicate")){var d=definition();if(defect.equals("speed"))d.put("speed",2);if(defect.equals("follow-distance"))d.put("follow-distance",50);if(defect.equals("legs"))d.put("legs",List.of());if(defect.equals("path"))d.put("legs",List.of(Map.of("objective",0,"path",List.of(List.of(3,64,3),List.of(99,64,3)))));if(defect.equals("duplicate"))d.put("legs",List.of(Map.of("objective",0,"path",List.of(List.of(3,64,3),List.of(9,64,3))),Map.of("objective",0,"path",List.of(List.of(3,64,3),List.of(9,64,3)))));assertThrows(IllegalArgumentException.class,()->EscortContent.parse(root(d),catalog(),rules()),defect);}}
}
